    /// <summary>Brand gradients, left to right. Now is the signature: logo ring, splash, celebrations.</summary>
    public static class HichgahGradients
    {
        public static readonly Color[] NowStops = { HichgahColors.Hex(0x7B3FFF), HichgahColors.Hex(0xFF4FA3), HichgahColors.Hex(0xFF9F1C) };
        public static Gradient Now => Build(NowStops);
        public static readonly Color[] DuskStops = { HichgahColors.Hex(0x4A1BC9), HichgahColors.Hex(0x9A22C8), HichgahColors.Hex(0xC8186E) };
        public static Gradient Dusk => Build(DuskStops);

        static Gradient Build(Color[] stops)
        {
            var colors = new GradientColorKey[stops.Length];
            for (int i = 0; i < stops.Length; i++)
                colors[i] = new GradientColorKey(stops[i], stops.Length == 1 ? 0f : i / (stops.Length - 1f));
            var gradient = new Gradient();
            gradient.SetKeys(colors, new[] { new GradientAlphaKey(1f, 0f), new GradientAlphaKey(1f, 1f) });
            return gradient;
        }
    }

